"""Reusable real-imagery 3D component for every retained Streamlit GIS view."""
from __future__ import annotations
import json, os
import streamlit as st
import streamlit.components.v1 as components
from core.config import BASE_DIR
from services.gis_service import load_gis_stations, load_gate_pump_points

def render_3d_map(latest=None,height=580):
    payload={'stations':list(load_gis_stations()),'facilities':list(load_gate_pump_points()),'rivers':json.loads((BASE_DIR/'data/gis/river_network_full.geojson').read_text(encoding='utf-8-sig'))}
    serialized=json.dumps(payload,ensure_ascii=False).replace('</','<\\/')
    base=os.environ.get('HYDRO_CESIUM_ASSET_URL','https://cesium.com/downloads/cesiumjs/releases/1.131/Build/Cesium/').rstrip('/')+'/'
    import html
    base=html.escape(base,quote=True)
    template=r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><link rel="stylesheet" href="__BASE__Widgets/widgets.css"><script src="__BASE__Cesium.js"></script><style>html,body,#view{width:100%;height:100%;padding:0;margin:0;background:#102319;color:#d4e6d4;font:12px sans-serif}#status,#detail{position:absolute;background:#10261de8;border:1px solid #507157;border-radius:5px;padding:10px;z-index:3;max-width:340px;line-height:1.8}#status{top:12px;left:12px}#detail{bottom:35px;left:12px}button{position:absolute;right:12px;top:12px;z-index:5;color:#dcf0d9;background:#294c32;border:1px solid #6e9471;padding:8px;border-radius:4px}.cesium-widget-credits{font-size:9px!important}</style></head><body><div id="view"></div><div id="status">实景三维 · 正在连接卫星影像与地形</div><div id="detail">站点与闸站来自原项目，闸站为三维符号。河道索引是断面中心连线，投影转换假定 EPSG:4528，待复核。<br>业务水位为吴淞高程，不与卫星地形高度直接混用。</div><button id="home">区域复位</button><script>const data=__DATA__;const C=Cesium;C.Ion.defaultAccessToken='';try{const v=new C.Viewer('view',{baseLayer:false,baseLayerPicker:false,timeline:false,animation:false,geocoder:false,homeButton:false,sceneModePicker:false,navigationHelpButton:false,fullscreenButton:false,infoBox:false,selectionIndicator:false,requestRenderMode:true});v.imageryLayers.addImageryProvider(new C.UrlTemplateImageryProvider({url:'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',maximumLevel:19,credit:'Esri, Vantor, Earthstar Geographics and the GIS User Community'}));C.ArcGISTiledElevationTerrainProvider.fromUrl('https://elevation3d.arcgis.com/arcgis/rest/services/WorldElevation3D/Terrain3D/ImageServer').then(t=>{v.terrainProvider=t;document.getElementById('status').textContent='真实卫星影像 + 真实地形 · 左键平移 / Ctrl 拖动倾斜';}).catch(()=>document.getElementById('status').textContent='地形服务未连接，当前仅影像覆于椭球面');for(const s of data.stations)v.entities.add({name:s.station_name,position:C.Cartesian3.fromDegrees(s.lng,s.lat,15),point:{pixelSize:7,color:C.Color.fromCssColorString('#78e4ae'),outlineColor:C.Color.WHITE,outlineWidth:1,heightReference:C.HeightReference.RELATIVE_TO_GROUND,disableDepthTestDistance:Infinity}});for(const s of data.facilities)v.entities.add({name:s.facility_name,position:C.Cartesian3.fromDegrees(s.lng,s.lat,20),box:{dimensions:new C.Cartesian3(30,25,40),heightReference:C.HeightReference.RELATIVE_TO_GROUND,material:C.Color.fromCssColorString('#dfbd7d')}});for(const f of data.rivers.features)v.entities.add({name:f.properties.name,polyline:{positions:C.Cartesian3.fromDegreesArray(f.geometry.coordinates.flatMap(p=>[p[0],p[1]])),clampToGround:true,width:2,material:C.Color.fromCssColorString('#8ed3e5')}});function home(){v.camera.flyTo({destination:C.Cartesian3.fromDegrees(120.413,31.448,23500),orientation:{heading:0,pitch:C.Math.toRadians(-48),roll:0},duration:0});}home();document.getElementById('home').onclick=home;v.screenSpaceEventHandler.setInputAction(m=>{const p=v.scene.pick(m.position);if(p&&p.id)document.getElementById('detail').textContent=p.id.name+' · 位置来自原项目，不表示在线设备状态';},C.ScreenSpaceEventType.LEFT_CLICK);}catch(e){document.getElementById('status').textContent='三维渲染未开启：请使用支持 WebGL 的浏览器并开启硬件加速。';}</script></body></html>'''
    components.html(template.replace('__BASE__',base).replace('__DATA__',serialized),height=height,scrolling=False)
    st.caption('Esri 实景影像与地形；原项目 GIS 参考资料；业务水位与地形高程基准独立。')
